```dart
import 'package:collection/collection.dart';

class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitEarnedOrLoss;

  const Transaction({required this.coinName, required this.datetime, required this.profitEarnedOrLoss});
}

List<Transaction> sortTransactionsByProfit(List<Transaction> transactions) {
  return transactions.sort((a, b) => a.profitEarnedOrLoss.compareTo(b.profitEarnedOrLoss));
}

List<Transaction> sortTransactionsByAverageProfit(List<Transaction> transactions) {
  final totalProfit = transactions.map((t) => t.profitEarnedOrLoss).reduce((a, b) => a + b);
  final averageProfit = totalProfit / transactions.length;
  return transactions.map((t) => Transaction(coinName: t.coinName, datetime: t.datetime, profitEarnedOrLoss: t.profitEarnedOrLoss - averageProfit)).toList();
}

List<Transaction> sortTransactionsByAverageLoss(List<Transaction> transactions) {
  final totalLoss = transactions.map((t) => t.profitEarnedOrLoss).reduce((a, b) => a + b);
  final averageLoss = totalLoss / transactions.length;
  return transactions.map((t) => Transaction(coinName: t.coinName, datetime: t.datetime, profitEarnedOrLoss: averageLoss - t.profitEarnedOrLoss)).toList();
}

List<Transaction> getTopThreeCoinsWithHighestAverageProfit(List<Transaction> transactions) {
  final sortedTransactions = sortTransactionsByAverageProfit(transactions);
  return sortedTransactions.take(3).toList();
}

List<Transaction> getTopThreeCoinsWithHighestAverageLoss(List<Transaction> transactions) {
  final sortedTransactions = sortTransactionsByAverageLoss(transactions);
  return sortedTransactions.take(3).toList();
}
```

