import com.atlassian.jira.issue.Issue
import com.atlassian.jira.issue.IssueManager
import com.atlassian.jira.project.Project
import com.atlassian.jira.project.ProjectManager
import com.atlassian.jira.user.User

def blockChecklistField = "Blocking Checklist"

def isBlockingChecklistComplete(issue) {
    def checklistItems = issue.getCustomFieldValue(blockChecklistField)
    return checklistItems?.every { item -> item.isDone() } ?? false
}

def canMoveToNextColumn(issue, nextColumnId) {
    def project = issue.getProjectObject()
    def projectManager = project.getProjectManager()
    def column = projectManager.getColumnById(nextColumnId)

    return !column.isLocked() && !isBlockingChecklistComplete(issue)
}

def moveIssueToNextColumn(issue, nextColumnId) {
    def project = issue.getProjectObject()
    def projectManager = project.getProjectManager()
    def column = projectManager.getColumnById(nextColumnId)

    if (canMoveToNextColumn(issue, nextColumnId)) {
        issue.move(column)
    } else {
        println("Issue cannot be moved to the next column because the blocking checklist is not complete.")
    }
}

