```javascript
function swapAdjectives(sentence) {
  const words = sentence.split(" ");
  const adjectives = [];
  let currentWord;

  for (let i = 0; i < words.length; i++) {
    currentWord = words[i];

    if (currentWord === "beautiful" || currentWord === "green") {
      adjectives.push(currentWord);
    } else if (adjectives.length > 1) {
      const lastAdjective = adjectives[adjectives.length - 1];
      words.splice(i, 0, lastAdjective);
      adjectives.pop();
    }
  }

  return words.join(" ");
}

const sentence = "Beautiful green trees are in the park";
const result = swapAdjectives(sentence);
console.log(result); // Output: "Green beautiful trees are in the park"
