import org.sox4j.Sox;
import org.sox4j.SoxException;
import org.sox4j.SoxOutput;

public class AudioMixer {
    public static void main(String[] args) throws SoxException {
        // Read the first audio file
        SoxInput input1 = new SoxInput("file1.wav");

        // Read the second audio file
        SoxInput input2 = new SoxInput("file2.wav");

        // Create a mixer object
        SoxMixer mixer = new SoxMixer();

        // Add the input streams to the mixer
        mixer.addInput(input1);
        mixer.addInput(input2);

        // Create an output stream
        SoxOutput output = new SoxOutput("output.wav");

        // Mix the audio files
        mixer.mix(output);

        // Close the inputs and output
        input1.close();
        input2.close();
        output.close();
    }
}
```
