#include <iostream>
#include <string>
#include <sstream>
#include <stdexcept>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 1) {
        return a;
    } else if (n == 2) {
        return b;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int num1, num2, sequence_length;

    cout << "Enter the first two integers: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> num1 >> num2;

    if (!iss || cin.fail()) {
        throw runtime_error("Invalid input");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> sequence_length;

    if (sequence_length <= 0) {
        throw runtime_error("Invalid input");
    }

    int result[sequence_length];
    for (int i = 0; i < sequence_length; i++) {
        result[i] = fibonacci(i + 2, num1, num2);
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < sequence_length - 1; i++) {
        cout << result[i] << ", ";
    }
    cout << result[sequence_length - 1] << endl;

    return 0;
}
```

