    if (n == 0) {
        return a;
    } else if (n == 1) {
        return b;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int first, second, count;

    cout << "Enter the first two integers: ";
    getline(cin, input);
    istringstream iss(input);

    if (!(iss >> first >> second)) {
        cout << "Invalid input. Please enter two integers." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> count;

    if (count < 2) {
        cout << "Invalid input. Please enter a positive integer." << endl;
        return 1;
    }

    int sequence[count];
    sequence[0] = first;
    sequence[1] = second;

    for (int i = 2; i < count; i++) {
        sequence[i] = fibonacci(i, second, first + second);
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < count; i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
