```swift
import Foundation

struct RaceCar {
    let name: String
    let topSpeed: Double
}

let cars = [
    RaceCar(name: "Ferrari 488 GTB", topSpeed: 200.0),
    RaceCar(name: "McLaren 720S", topSpeed: 210.0),
    RaceCar(name: "Lamborghini Huracan Performante", topSpeed: 202.0)
]

func compareTopSpeeds(cars: [RaceCar]) -> String {
    var fastestCar: RaceCar?
    var fastestTime: Double = Double.infinity

    for car in cars {
        if car.topSpeed > fastestTime {
            fastestCar = car
            fastestTime = car.topSpeed
        }
    }

    guard let fastestCar = fastestCar else {
        return "No cars have a top speed."
    }

    return "The fastest car is \(fastestCar.name) with a top speed of \(fastestCar.topSpeed) mph."
}

print(compareTopSpeeds(cars: cars))
```
