function createVerticalVideo() {
  // Set up the project settings
  var projectSettings = {
    width: 1920,
    height: 1080,
    frameRate: 30,
    duration: 10
  };

  // Create a new project
  var project = app.project.create(projectSettings);

  // Import the video files
