    videoFile.name = "Video " + (i + 1);
  }

  // Stack the video files
  var videoLayer1 = project.layers.add(videoFiles[0], [0, 0]);
  var videoLayer2 = project.layers.add(videoFiles[1], [0, videoLayer1.height]);

  // Add subtitles to the top half of the video
  var subtitleText = "This is a subtitle";
  var subtitleLayer = project.layers.add(subtitleText, [0, 0]);
  subtitleLayer.resize(project.width, videoLayer1.height / 2);
  subtitleLayer.alignment = [0.5, 0.5];
