  subtitleLayer.fontSize = 24;
  subtitleLayer.color = [0, 0, 0];
  subtitleLayer.textAlign = "center";
  subtitleLayer.lineHeight = 1.2;

  // Export the final video
  var exportSettings = {
    format: "MP4",
    quality: 100,
    codec: "H.264"
  };
  project.exportFile("vertical_video.mp4", exportSettings);
}

// Run the script
createVerticalVideo();
```

