    future_perfect = '^(?<verb>\w+)\b\s*(?:will|shall)\s*(?:have)\s*(?:been)$';

    % Match the tense in the sentence
    match = regexp(sentence, [present_simple, past_simple, future_simple, present_continuous, past_continuous, future_continuous, present_perfect, past_perfect, future_perfect], 'match');

    % Return the corresponding tense name
    if ~ismember(match, '')
        tense = regexp(sentence, '[present_simple, past_simple, future_simple, present_continuous, past_continuous, future_continuous, present_perfect, past_perfect, future_perfect]', 'match');
