			Type:  schema.ParseType(typeStr),
		}

		fields = append(fields, fieldSchema)
	}

	schemaDef := schema.Schema{
		Name:  structName,
		Type:  schema.RecordType,
		Fields: fields,
	}

	schemaData, err := schema.JSONSchema(schemaDef)
	if err != nil {
		fmt.Println("Error generating JSON schema:", err)
		return
	}

	err = ioutil.WriteFile("struct.avsc", schemaData, 0644)
	if err != nil {
		fmt.Println("Error writing file:", err)
		return
	}

	fmt.Println("Avro schema generated successfully

