import datetime

class PomodoroTimer:
    def __init__(self, work_interval_length=25, short_break_length=5, long_break_length=15, work_style="focused"):
        self.work_interval_length = work_interval_length
        self.short_break_length = short_break_length
        self.long_break_length = long_break_length
        self.work_style = work_style

    def calculate_optimal_interval_length(self, individual_productivity_level):
        optimal_interval_length = round(individual_productivity_level * self.work_interval_length)
        return optimal_interval_length

    def schedule_work_intervals(self, max_intervals_per_day, interval_length, work_style):
