Here's a simple script for Unity that takes an audio file as input and displays a visualizer in time with the music. This script uses the AudioSource component to play the audio file and the Graphics Raycaster to detect when the user clicks on the visualizer.

```csharp
using UnityEngine;
using UnityEngine.Audio;
using UnityEngine.UI;

public class MusicVisualizer : MonoBehaviour
{
    public AudioSource audioSource;
    public GraphicRaycaster raycaster;
    public float sensitivity = 0.1f;
    public Color[] colors = new Color[256];

    private float volume;
    private int sampleRate;
    private float[] samples;
    private int sampleIndex;
    private Vector2 mousePosition;

    void Start()
    {
        audioSource = GetComponent<AudioSource>();
        raycaster = GetComponent<GraphicsRaycaster>();
        sampleRate = audioSource.outputSampleRate;
        samples = new float[sampleRate];
        sampleIndex = 0;
    }

    void Update()
    {
        volume = audioSource.volume;
        sampleIndex++;
        if (sampleIndex >= sampleRate)
        {
            sampleIndex = 0;
            audioSource.GetOutputData(samples, sampleIndex);
        }

        float amplitude = Mathf.Abs(samples[sampleIndex]);
        color = colors[Mathf.RoundToInt(amplitude * (colors.Length - 1))];
        GetComponent<Renderer>().material.color = color;

        mousePosition = Input.mousePosition;
        float x = mousePosition.x / Screen.width;
        float y = mousePosition.y / Screen.height;
        float distance = Vector2.Distance(new Vector2(x, y), transform.position);
        if (distance < sensitivity)
        {
            Debug.Log("Clicked!");
        }
    }
}
```

This script can be attached to a GameObject in your Unity project, and you can customize the visualizer's appearance and behavior by adjusting the properties of the components used in this script.

