```csharp
using UnityEngine;
using UnityEngine.Audio;

public class Visualizer : MonoBehaviour
{
    public AudioSource audioSource;
    public float waveHeight = 10f;
    public float frequencyRange = 0.1f;

    private LineRenderer lineRenderer;

    void Start()
    {
        lineRenderer = GetComponent<LineRenderer>();
        lineRenderer.positionCount = 2;
        lineRenderer.SetPosition(0, Vector3.zero);
        lineRenderer.SetPosition(1, Vector3.up * waveHeight);
    }

    void Update()
    {
        if (audioSource == null)
        {
            return;
        }

        float amplitude = audioSource.volume * waveHeight;
        float frequency = audioSource.time * frequencyRange;

        lineRenderer.SetPosition(1, Vector3.up * amplitude * Mathf.Sin(frequency));
    }
}
```

3. Configure the visualizer:
   - In the "Visualizer" script, adjust the values of `waveHeight`, `frequencyRange`, and `amplitude` to suit your preferences.
   - You can also experiment with different line styles and colors by adjusting the properties of the "LineRenderer" component.

4. Test the visualizer:
   - Attach the "Visualizer" script to the game object you created earlier.
   - Set the "AudioSource" component to the audio clip you imported earlier.
   - Play the audio clip in the Unity editor to see the visualizer in action.

