def calculate_area(shape: str, length: float, width: float) -> float:
    """Calculates the area of a shape based on its length and width."""
    if shape == "rectangle":
        return length * width
    elif shape == "circle":
        return 3.14 * (length ** 2)
    else:
        raise ValueError("Invalid shape.")

