    char *c_string = malloc(sizeof(char) * (strlen(argv[0]) + 1));
    strcpy(c_string, argv[0]);
    printf("Converted string: %s\n", c_string);
    free(c_string);
    return 0;
}
```

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    char *c_string = (char *)malloc(sizeof(char) * (argc + 1));
    strcpy(c_string, "");

    for (int i = 0; i < argc; i++) {
        strcat(c_string, argv[i]);
        strcat(c_string, " ");
    }

    printf("C string: %s\n", c_string);

    free(c_string);

    return 0;
}
```

```c
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    char *cstring = malloc(sizeof(char) * (argc + 1));
    int i;

    for (i = 0; i < argc; i++) {
        strcat(cstring, argv[i]);
        if (i != argc - 1) {
            strcat(cstring, " ");
        }
    }

    printf("C-string: %s\n", cstring);

    free(cstring);

    return 0;
}
```

