Here's a simple decorator for Nest.js middleware that checks the NODE_ENV variable and returns false if it's not equal to 'true'.

```typescript
import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';

@Injectable()
export class EnvGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest();
    const nodeEnv = process.env.NODE_ENV;

    return nodeEnv === 'true';
  }
}
```

You can use this decorator in your Nest.js controller or service like this:

```typescript
import { Controller, Get } from '@nestjs/common';
import { EnvGuard } from './env-guard';

@Controller('your-controller-path')
export class YourController {
  constructor(private readonly envGuard: EnvGuard) {}

  @Get()
  async getData() {
    await this.envGuard.canActivate(this); // Check NODE_ENV and return false if it's not equal to 'true'

    // Your business logic here
  }
}
```

Here's a simple decorator for Nest.js middleware that checks the `NODE_ENV` variable and calls the next middleware function or returns `false` based on the environment:

```typescript
import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';

@Injectable()
export class EnvGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const req = context.switchToHttp().getRequest();
    const nodeEnv = process.env.NODE_ENV;

    if (nodeEnv === 'true') {
      return true;
    } else {
      return false;
    }
  }
}
```

Now you can use this guard in your Nest.js controller to restrict access to certain endpoints based on the environment:

```typescript
import { Controller, Get, UseGuards } from '@nestjs/common';
import { EnvGuard } from './env-guard';

@Controller('api')
export class ApiController {
  @Get()
  @UseGuards(EnvGuard)
  getData(): string {
    // Your API endpoint logic here
  }
}
```

In this example, the `getData` method will only be accessible when the `NODE_ENV` variable is set to `true`. If it's set to `false`, the request will be rejected with a status code of `403 Forbidden`.

