To create a simple toast notification using React Context, follow these steps:

1. First, create a `ToastContext` file to handle the context and toast messages.

```javascript
import React, { createContext, useReducer } from 'react';

const ToastContext = createContext();

function toastReducer(state, action) {
  switch (action.type) {
    case 'SHOW_TOAST':
      return { ...state, showToast: true, message: action.message };
    case 'HIDE_TOAST':
      return { ...state, showToast: false, message: null };
    default:
      return state;
  }
}

export function ToastProvider({ children }) {
  const [toastState, dispatch] = useReducer(toastReducer, {
    showToast: false,
    message: null,
  });

  return (
    <ToastContext.Provider value={{ toastState, dispatch }}>
      {children}
    </ToastContext.Provider>
  );
}

export function useToast() {
  const { toastState, dispatch } = React.useContext(ToastContext);
  return { toastState, dispatch };
}
```

