public class DateDurationCalculator {
    public static void main(String[] args) {
        ZonedDateTime start = ZonedDateTime.of(2022, 1, 1, 10, 0, 0, 0, ZoneId.of("Europe/London"));
        ZonedDateTime end = ZonedDateTime.of(2022, 1, 1, 15, 30, 0, 0, ZoneId.of("America/New_York"));
        Duration duration = Duration.between(start, end);
        System.out.println("Duration: " + duration);
        // Calculate the difference in time zones
        ZoneId europeLondonTimeZone = ZoneId.of("Europe/London");
        ZoneId americaNewYorkTimeZone = ZoneId.of("America/New_York");
        long timeDifference = europeLondonTimeZone.getRules().getOffset(start).getTotalSeconds() - americaNewYorkTimeZone.getRules().getOffset(end).getTotalSeconds();
        System.out.println("Time difference: " + timeDifference);
        // Adjust the start time to account for the time difference
        start = start.minusSeconds(timeDifference);
        duration = Duration.between(start, end);
        System.out.println("Adjusted duration: " + duration);
    }
}
```
