To prevent your planets from being too close together, you can implement a simple collision detection mechanism. Here's an updated version of the `generateRandomPlanets` function that checks for collisions and adjusts the planet's position if it's too close to another planet:

```javascript
const generateRandomPlanets = (numPlanets, minDistance) => {
  const planets = [];
  let attempts = 0;

  while (planets.length < numPlanets && attempts < 100) {
    attempts++;

    const planet = {
      position: [
        randomPosition(-30, 30),
        randomPosition(-30, 30),
        randomPosition(-30, 30),
      ],
      size: randomSize(1, 5) * scale,
      color: randomColor(),
      ringSize: 0.2 * scale,
      ringColor: randomColor(),
      ringNoise: 0.3 * scale,
    };

    // Check if planet is too close to any existing planet
    const tooClose = planets.some((p) =>
      p.position.some((coord, index) => {
        return Math.abs(coord - planet.position[index]) < minDistance;
      })
    );

    if (!tooClose) {
      planets.push(planet);
    } else {
      // Adjust the planet's position if it's too close to another planet
      const closestPlanet = planets.reduce((prev, curr) => {
        if (prev.position.some((coord, index) => {
          return Math.abs(coord - planet.position[index]) < minDistance;
        })) {
          return prev;
        } else {
          return curr;
        }
      });

      const direction = closestPlanet.position.sub(planet.position).normalize();
      planet.position.add(direction.multiplyScalar(minDistance / 2));
