                return True
            }
            if ($group.MemberOf -contains $sid) {
                return True
            }
        }
    }

    return False
}

# Recursively check folders for SIDs in SIDHistory
function CheckFolderForSIDsInSIDHistory($folderPath) {
    Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
        $acl = (Get-Acl -Path $_.FullName).Access
        foreach ($access in $acl) {
            if ($access.IdentityReference -match '^S-1-5-21-') {
                $sid = New-Object System.Security.Principal.SecurityIdentifier($access.IdentityReference)
                if (CheckSIDInSIDHistory($sid)) {
                    Write-Host "ACL in $($_.FullName) references a SID in SIDHistory: $($sid)"
                }
            }
        }

        CheckFolderForSIDsInSIDHistory($_.FullName)
    }
}

# Start the search
CheckFolderForSIDsInSIDHistory($folderPath)
