# Define the function to check if an SID is present in the SIDHistory of any user or group in the domain
function CheckSIDInSIDHistory($sid) {
    $domain = (Get-ADDomain).Name
    $searcher = New-Object System.DirectoryServices.DirectorySearcher($domain)
    $searcher.Filter = "(objectCategory=person)(SIDHistory=$sid)"
    $results = $searcher.FindAll()
    return ($results.Count -gt 0)
}

# Define the function to recursively check folders for SIDs in SIDHistory
function CheckFolderACLsForSIDHistory($folderPath) {
